import type { ZodType } from 'zod';
export type Point = { x: number; y: number };
export type Bounds = Point & { width: number; height: number };
export type ElementType = 'pen' | 'rectangle' | 'ellipse' | 'line' | 'arrow' | 'text';
export type BoardElement = Bounds & { id: string; type: ElementType; color: string; fill: string; strokeWidth: number; fontSize: number; text: string; points: Point[] };
export type BoardDocument = { version: 1; elements: BoardElement[]; background: 'dots' | 'grid' | 'plain'; snap: boolean };
export const MAX_ELEMENTS: number;
export const MAX_POINTS: number;
export const GRID_SIZE: number;
export const boardElementSchema: ZodType<BoardElement>;
export const boardDocumentSchema: ZodType<BoardDocument>;
export function emptyDocument(): BoardDocument;
export function elementBounds(element: BoardElement): Bounds;
export function sceneBounds(elements: BoardElement[], padding?: number): Bounds;
export function segmentDistance(point: Point, start: Point, end: Point): number;
export function hitTest(element: BoardElement, point: Point, tolerance?: number, interior?: boolean): boolean;
export function pickElement(elements: BoardElement[], point: Point, tolerance?: number, interior?: boolean): BoardElement | null;
export function arrowHead(element: BoardElement): string;
export function makeElement(type: ElementType, x: number, y: number, options?: Partial<BoardElement>): BoardElement;
export function makePreset(type: 'array' | 'tree' | 'graph', center: Point): BoardElement[];
export function serializeSvg(document: BoardDocument, background?: string): string;
